local _, WFJ = ...
WFJ.Data.add("quest", {
  [99156] = { "Pattuglia di retroguardia", "Porta il Riptear's Heart alla Guardia della Morte Linnea.", "Maledizione! È arrivato un nuovo rapporto mentre eri di pattuglia. Un abominio rinnegato è stato avvistato mentre vagava nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧ orientali, vicino alla ⟦Venomweb Vale=Valle Tela Venefica⟧.\n\nC'è qualcosa che non va. Gli abomini non oltrepassano il Bulwark inosservati.\n\nTieni la faccenda strettamente riservata. Detto questo, una creatura del genere non cadrà facilmente: ti serviranno alleati, se non vuoi diventare il suo prossimo pasto.\n\nPorta a termine il compito e sarai ricompensat<o/a> come si deve. Portami il suo cuore come prova dell'impresa.", "Hai risolto il nostro piccolo problema?", "Sei la prova dell'astuzia e della coordinazione che tutti i Reietti possiedono, qualcosa che il Flagello senza cervello non avrà mai.\n\nTi prego, accetta questo come ringraziamento per i tuoi sforzi, come promesso.", 0x889b08c3, 0x64da93a0, 0x08dcb58d, 0x45c20a1e, 0xc963fae0, "....." },
  [99159] = { "In cerca di calore", "Raccogli $N1 pezzi di legna da ardere.", "Il mio focolare è aperto per scaldare chiunque, ma vorrei chiederti di aiutarmi, se puoi.\n\nMi serve solo altra legna da ardere. Di solito me ne occuperei di persona, ma altre faccende mi hanno tenuto impegnato.", "Che la Luce ti guidi nei tuoi compiti.", "Ah, perfetto. Questa andrà bene: quella troppo bagnata per usarla subito la lascerò ad asciugare.\n\nOra, se te la senti, ho altri compiti per cui mi farebbe comodo un aiuto.", 0xd2e96c81, 0xe7dfe34d, 0x440461b1, 0x02ed172f, 0x50273776, "....." },
  [99160] = { "L'ira di Rime", "Distruggi $N1 elementali del ghiaccio minori.", "Avrai notato gli elementali qui vicino. Qualche giorno fa una lastra di roccia e ghiaccio si è staccata dalle vette e li ha aizzati.\n\nQueste montagne gelate sono già insidiose per un nano o un umano qualunque, anche senza che gli elementi prendano forma. Combattere non fa più per me, quindi ogni spirito che riuscirai a uccidere aiuterà a rendere la strada più sicura.", nil, "Avrei voluto che potessimo semplicemente placarli. Purtroppo andava oltre le mie conoscenze, ed erano troppo pericolosi per lasciarli liberi.", 0x53be69cf, 0xaa060f30, 0x59b45096, nil, 0x95b19818, "...m." },
  [99161] = { "L'ira di Rime", "Uccidi Avala e recupera il suo nucleo.", "Ho notato che il primo elementale apparso dopo la frana era più grande dei suoi simili. E da quel che vedo, è stato la causa di qualche cambiamento del tempo e di altri piccoli smottamenti.\n\nL'ho chiamato «Avala»: se riuscirai a ucciderlo e a portarmi il suo nucleo come prova, ti ricompenserò.", "Guardati dall'inverno, amico.", "Che la Luce ti benedica, {class}. I tuoi sforzi rendono questa zona molto più sicura e, si spera, eviteranno morti inutili.", 0x53be69cf, 0xd6788d7a, 0x425a6958, 0x69cffb7c, 0x7feb3446, "....." },
  [99162] = { "Un freddo insidioso", "Raccogli i fucili dei montanari caduti.", "Persino i montanari di ⟦Ironforge=Forgiardente⟧ devono stare all'erta quando attraversano le vette di Dun Morogh. La neve e il ghiaccio che cadono segnano spesso la fine dei membri meno esperti.\n\nDopo una frana di solito cerco qualche segno di sopravvissuti o di vittime, pregando la Luce di non trovare nulla. Ma con gli elementi così agitati, ho evitato di allontanarmi troppo. Se cercherai i montanari dispersi e mi porterai i loro fucili, li riporterò a ⟦Ironforge=Forgiardente⟧.", "Di cosa hai bisogno?", "I montanari incidono il loro nome sul calcio del fucile. Aiuta a identificarli, nel caso succeda qualcosa. Li rimanderò a ⟦Ironforge=Forgiardente⟧: lì qualcuno li consegnerà alle famiglie.", 0x1ea8928b, 0x99bbd6c8, 0x3a1c1812, 0xece653c6, 0x49b853c2, "....." },
  [99191] = { "Una donazione di lana", nil, nil, "L'High Order al momento accetta donazioni di lana.\n\nUna donazione di sessanta pezze di lana ti varrà il pieno riconoscimento dell'High Order per la tua generosità. Sessanta pezze di lana dovrebbero bastare, per ora, alle necessità dell'High Order.\n\nSe hai con te le sessanta pezze di lana e sei <pronto/pronta> a donarle, posso prenderle subito.", nil, 0xaad71c6f, nil, nil, 0xec1c7e4f, nil, ".mm.m" },
  [99192] = { "Una donazione di seta", nil, nil, nil, nil, 0xaa4c5243, nil, nil, nil, nil, ".mmmm" },
  [99196] = { "Una donazione di lana", nil, nil, "I Windshaper al momento accettano donazioni di lana.\n\nUna donazione di sessanta pezze di lana ti varrà il pieno riconoscimento dei Windshaper per la tua generosità.\n\nSe hai con te le sessanta pezze di lana e sei <pronto/pronta> a donarle, posso prenderle subito.", nil, 0xaad71c6f, nil, nil, 0x23004f34, nil, ".mm.m" },
  [99197] = { "Una donazione di seta", nil, nil, nil, nil, 0xaa4c5243, nil, nil, nil, nil, ".mmmm" },
  [99260] = { "La missione di Fillion", "Parla con Elaadrin Evengale a Valanaar.", "Mi era stato affidato il compito di recuperare dati importanti sul flusso dell'energia elementale dalle Overlook Standing Stones. Quei dati sono vitali per i nostri piani di viaggiare in sicurezza tra Skywall e Azeroth. Senza di essi a sostegno dei nostri calcoli, i tentativi di guidare le nostre navi skycutter attraverso il piano elementale falliranno.\n\nA questo punto i dati sono probabilmente perduti, e non sono in condizioni di provare a raccoglierli di nuovo. Ho raccontato al magistro supremo il tuo ruolo nel salvarmi, e lui desidera parlarti di nuovo.", nil, "Grazie per aver salvato Fillion, {name}. Sono certo che ti abbia detto quanto siano vitali i dati che era stato mandato a recuperare.\n\nSenza quei dati, la prospettiva di aprire rotte sicure verso Azeroth è seriamente compromessa. Le nostre spie ci dicono che i Windshaper si sono procurati da sé i mezzi per attraversare i piani, e senza dubbio vogliono custodire gelosamente questo segreto.\n\nCome sempre, la loro arroganza dogmatica viene prima del bene del nostro popolo. Non sono molto meglio degli Al'Aketh.", 0x6d5d3e21, 0x73833554, 0x8b8e3ec7, nil, 0x6df73fd1, "...m." },
  [99267] = { "Una triste fine", nil, nil, nil, nil, 0xc0c4b3d4, nil, nil, nil, nil, ".mmmm" },
  [99411] = { "Kyle è scomparso!", "Ahab Wheathoof, al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ in Mulgore, vuole che tu dia da mangiare al suo amato cucciolo, Kyle il Frenetico.\n\nDai la Tender Strider Meat a Kyle e torna da Ahab Wheathoof.", "Aiuto, {name}! Il mio amato cucciolo, Kyle, è scappato! Sono sicuro che sta correndo per il ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧, sperduto e affamato.\n\nLo troverai e gli darai da mangiare? Quando avrà mangiato si calmerà e tornerà a casa.\n\nPer nutrirlo dovrai trovare del cibo. Il suo pasto preferito è la carne tenera di zampalunga. Va' verso est e dovresti trovare molti zampalunga. Cacciane uno e porta la sua carne succulenta a Kyle. Quando vedi Kyle in paese, posa la carne a terra e verrà di sicuro da te.", nil, nil, 0x8d0c2e05, 0x1d37ba26, 0xdd2f4f8d, nil, nil, "...mm" },
})
